use serde::{Deserialize, Serialize};

use crate::utils::tagged_enum;

tagged_enum! {
    /// What invoked a tool.
    #[derive(Serialize, Deserialize, Debug, Clone)]
    #[serde(tag = "type", rename_all = "snake_case")]
    pub enum ToolCaller {
        /// Tool invocation directly from the model.
        Direct(DirectCaller),
        /// Tool invocation generated by the `code_execution_20250825` server tool.
        #[serde(rename = "code_execution_20250825")]
        CodeExecution20250825(ServerToolCaller),
        /// Tool invocation generated by the `code_execution_20260120` server tool.
        #[serde(rename = "code_execution_20260120")]
        CodeExecution20260120(ServerToolCaller20260120),
    }
}

/// Tool invocation directly from the model.
#[cfg_attr(test, derive(utoipa::ToSchema))]
#[derive(Serialize, Deserialize, Debug, Clone, Default)]
#[non_exhaustive]
pub struct DirectCaller {}

/// Tool invocation generated by the `code_execution_20250825` server tool.
#[cfg_attr(test, derive(utoipa::ToSchema))]
#[derive(Serialize, Deserialize, Debug, Clone)]
#[non_exhaustive]
pub struct ServerToolCaller {
    /// The id of the server tool use block that invoked this tool.
    pub tool_id: String,
}

/// Tool invocation generated by the `code_execution_20260120` server tool.
#[cfg_attr(test, derive(utoipa::ToSchema))]
#[derive(Serialize, Deserialize, Debug, Clone)]
#[non_exhaustive]
pub struct ServerToolCaller20260120 {
    /// The id of the server tool use block that invoked this tool.
    pub tool_id: String,
}

impl ToolCaller {
    /// Creates a [`ToolCaller`] for an invocation coming straight from the model.
    pub fn direct() -> Self {
        ToolCaller::Direct(DirectCaller {})
    }
}

impl DirectCaller {
    /// Creates a new [`DirectCaller`].
    pub fn new() -> Self {
        Self::default()
    }
}

impl ServerToolCaller {
    /// Creates a new [`ServerToolCaller`] from the id of the invoking server tool use block.
    pub fn new(tool_id: impl Into<String>) -> Self {
        Self {
            tool_id: tool_id.into(),
        }
    }
}

impl ServerToolCaller20260120 {
    /// Creates a new [`ServerToolCaller20260120`] from the id of the invoking server tool use
    /// block.
    pub fn new(tool_id: impl Into<String>) -> Self {
        Self {
            tool_id: tool_id.into(),
        }
    }
}
